// Cloudflare Workers entry point that wraps the handler generated by @opennextjs/cloudflare.
//
// Gateway pattern (https://developers.cloudflare.com/workers/cache/examples/): the default entrypoint is not
// cached and runs on every request; it forwards cacheable requests to the `Site` entrypoint, which Workers Cache
// sits in front of (wrangler.jsonc `exports`). The Workers Cache key ignores the hostname, so everything that
// depends on the host stays in the gateway, outside the cache:
// - the bare domain permanently redirects to www, as it does on Vercel;
// - any host other than www (workers.dev test copies, previews) gets X-Robots-Tag noindex, added after the cache,
//   so a cached page can never carry noindex to www.byteverse.fyi. PRODUCTION_HOSTS (comma-separated) overrides
//   the production host list, e.g. for a local preview.
// API routes, admin pages and Next.js revalidation requests always run the app directly.
// scheduled() runs the daily publish job that Vercel Cron used to call (triggers.crons in wrangler.jsonc).
// @ts-nocheck - .open-next/worker.js is generated by `opennextjs-cloudflare build`.
import { WorkerEntrypoint } from "cloudflare:workers";
import handler from "../.open-next/worker.js";

const CANONICAL_HOST = "www.byteverse.fyi";
const APEX_HOST = "byteverse.fyi";
const UNCACHED_PATH = /^\/(?:api|admin)(?:\/|$)/;

function productionHosts(env) {
  return new Set((env.PRODUCTION_HOSTS || CANONICAL_HOST).split(",").map((host) => host.trim()).filter(Boolean));
}

function usesCache(request, url) {
  return (request.method === "GET" || request.method === "HEAD")
    && !request.headers.has("x-prerender-revalidate")
    && !UNCACHED_PATH.test(url.pathname);
}

export class Site extends WorkerEntrypoint {
  fetch(request) {
    return handler.fetch(request, this.env, this.ctx);
  }
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    if (url.hostname === APEX_HOST) {
      return Response.redirect(`https://${CANONICAL_HOST}${url.pathname}${url.search}`, 301);
    }
    const response = usesCache(request, url) ? await ctx.exports.Site.fetch(request) : await handler.fetch(request, env, ctx);
    if (productionHosts(env).has(url.hostname)) return response;
    const headers = new Headers(response.headers);
    headers.set("X-Robots-Tag", "noindex, nofollow");
    return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
  },

  async scheduled(controller, env, ctx) {
    if (!env.CRON_SECRET) throw new Error("CRON_SECRET is not set; scheduled posts were not published");
    const request = new Request(`https://${CANONICAL_HOST}/api/cron/publish`, {
      headers: { authorization: `Bearer ${env.CRON_SECRET}` },
    });
    const response = await handler.fetch(request, env, ctx);
    const body = await response.text();
    if (!response.ok) throw new Error(`Scheduled publish failed (HTTP ${response.status}): ${body.slice(0, 300)}`);
    console.log(`Scheduled publish (${controller.cron}): ${body.slice(0, 500)}`);
  },
};

// The ISR revalidation queue Durable Object must be exported from the entry point.
export { DOQueueHandler } from "../.open-next/worker.js";
